import { Connection, PublicKey } from "@solana/web3.js";
// @coral-xyz/anchor is CommonJS -- Node's ESM loader can't pull real named
// exports out of it at runtime. `type Idl` is safe as a named import since
// TypeScript erases type-only imports entirely; Program/AnchorProvider are
// actual values, so those come off the default export instead.
import anchorPkg from "@coral-xyz/anchor";
import fs from "node:fs";
import { PROGRAM_ID } from "./constants.js";
const { Program, AnchorProvider } = anchorPkg;
/**
 * Point IDL_PATH at the IDL your `anchor build` generates (target/idl/
 * stock_ramp.json) — same file the keeper and client both read from. This
 * server does NOT redefine the account layout; it decodes accounts through
 * the same IDL everything else trusts, so if the program upgrades, only
 * one file needs updating.
 */
const IDL_PATH = process.env.STOCK_RAMP_IDL_PATH ?? "./idl/stock_ramp.json";
function requireRpcUrl() {
    const url = process.env.SOLANA_RPC_URL;
    if (!url) {
        throw new Error("SOLANA_RPC_URL is not set. Which network this server reads from " +
            "changes what 'the best rate' or 'supported tokens' even means, so " +
            "it must be set explicitly rather than silently defaulting.");
    }
    return url;
}
const RPC_URL = requireRpcUrl();
let cachedProgram = null;
let cachedIdl = null;
export function getConnection() {
    return new Connection(RPC_URL, "confirmed");
}
export function getIdl() {
    if (!cachedIdl) {
        if (!cachedProgram) {
            throw new Error("getIdl() called before getProgram(). Call getProgram() first.");
        }
    }
    return cachedIdl;
}
/**
 * Read-only Anchor program client. No wallet/signer — this server never
 * signs anything; every mutating action goes through the Solana Pay
 * transaction-request flow instead, signed by the person's own wallet.
 */
export function getProgram() {
    if (cachedProgram)
        return cachedProgram;
    if (!fs.existsSync(IDL_PATH)) {
        throw new Error(`StockRamp IDL not found at ${IDL_PATH}. Set STOCK_RAMP_IDL_PATH to ` +
            `the IDL generated by \`anchor build\` (target/idl/stock_ramp.json).`);
    }
    const idl = JSON.parse(fs.readFileSync(IDL_PATH, "utf-8"));
    cachedIdl = idl;
    const idlAddress = idl.address;
    if (!idlAddress) {
        throw new Error(`IDL at ${IDL_PATH} has no top-level "address" field (Anchor 0.30+ requires it). ` +
            `Re-export with a current anchor-cli, or add "address": "${PROGRAM_ID.toString()}" manually.`);
    }
    if (idlAddress !== PROGRAM_ID.toString()) {
        throw new Error(`IDL address (${idlAddress}) does not match STOCK_RAMP_PROGRAM_ID ` +
            `(${PROGRAM_ID.toString()}). Refusing to proceed — likely a devnet/mainnet ` +
            `mismatch, or a stale IDL from a previous deployment.`);
    }
    const connection = getConnection();
    // Dummy read-only "wallet" — never signs anything. This server only ever
    // calls .account.<name>.fetch()/.all(), never .methods(), so
    // signTransaction/signAllTransactions are unreachable but must exist to
    // satisfy Anchor's Wallet interface shape.
    const readOnlyWallet = {
        publicKey: PublicKey.default,
        signTransaction: async () => {
            throw new Error("This MCP server is read-only and must never sign transactions.");
        },
        signAllTransactions: async () => {
            throw new Error("This MCP server is read-only and must never sign transactions.");
        },
    };
    const provider = new AnchorProvider(connection, readOnlyWallet, {
        commitment: "confirmed",
    });
    cachedProgram = new Program(idl, provider);
    return cachedProgram;
}
